import * as React from 'react';
import {motion,MotionConfig} from 'motion/react';
import {Search,ArrowLeft,ArrowUpRight,Sun,Moon,Check,RotateCcw,Copy,Box,Film,Map,PenTool,Camera,Code2,Grid3X3} from 'lucide-react';
import {widgetCatalog,getWidgetDefinition,type WidgetId} from './widgets/catalog';
import {WidgetView,type WidgetValue} from './widgets/widget-view';
import {WidgetFrame,ConnectionBanner,type WidgetState,type DockPosition} from './components/system/controls';
import {Button,Input,Select,Badge,Wordmark,AgentCore,Timeline,TooltipProvider} from './components/nbrain';
import {makeFixture} from './demo-fixtures';
const categories=['All',...new Set(widgetCatalog.map(d=>d.category))];
function EngineMock({id,value,onValueChange}:{id:WidgetId;value:WidgetValue;onValueChange:(v:WidgetValue)=>void}){const [strokes,setStrokes]=React.useState<string[]>([]);const pen=React.useRef(false);const line=React.useRef('');
 if(['timeline','playercontrol','review'].includes(id))return <div className="demo-timeline"><div className="demo-film-frame"><Film size={36}/><span>HARBOR / SH_010</span></div><Timeline position={value.scalar} onSeek={n=>onValueChange({...value,scalar:n})}/></div>;
 if(id==='drawing_canvas')return <svg className="demo-drawing" viewBox="0 0 500 240" aria-label="Demo drawing surface" onPointerDown={e=>{pen.current=true;e.currentTarget.setPointerCapture(e.pointerId);const r=e.currentTarget.getBoundingClientRect();line.current=`M${(e.clientX-r.left)/r.width*500} ${(e.clientY-r.top)/r.height*240}`;setStrokes(s=>[...s,line.current])}} onPointerMove={e=>{if(!pen.current)return;const r=e.currentTarget.getBoundingClientRect();line.current+=`L${(e.clientX-r.left)/r.width*500} ${(e.clientY-r.top)/r.height*240}`;setStrokes(s=>[...s.slice(0,-1),line.current])}} onPointerUp={()=>{pen.current=false}} onPointerCancel={()=>{pen.current=false}}><path d="M100 180L200 70 285 170 330 110 410 180" stroke="#aebed355" fill="none" strokeWidth="2"/>{strokes.map((d,i)=><path key={i} d={d} stroke="#8eadff" fill="none" strokeWidth="2"/>)}<text x="20" y="28">DRAW HERE / DEMO CANVAS</text></svg>;
 if(id==='stage_plan')return <svg className="demo-stage-plan" viewBox="0 0 500 240" aria-label="Stage layout design preview"><rect x="40" y="35" width="420" height="170" rx="8"/><rect x="155" y="48" width="190" height="20"/><path d="M135 150L195 80 220 155ZM365 150L295 80 280 155Z"/><circle cx="135" cy="150" r="8"/><circle cx="365" cy="150" r="8"/><circle cx="250" cy="125" r="10"/><text x="218" y="194">LED VOLUME</text></svg>;
 if(id==='plates')return <div className="demo-plate-map"><svg viewBox="0 0 500 240" aria-label="Driving plate route preview"><path d="M0 190L100 165 210 110 340 145 500 40M80 0L120 80 210 110 180 240M280 0L260 80 340 145 390 240"/><path className="route" d="M70 177L100 165 210 110 340 145 430 83"/><circle cx="210" cy="110" r="6"/></svg><div><Map size={15}/><span>Route / Coastal drive · 360° plate</span></div></div>;
 if(['image','streamdiffusion'].includes(id))return <div className="demo-image-study"><span>LIGHT STUDY / 01</span><div/><strong>{id==='streamdiffusion'?'Live diffusion preview':'Silver / blue hour'}</strong></div>;
 return <div className={'demo-wireframe demo-engine-'+id}><svg viewBox="0 0 500 240" aria-label={id+' engine design preview'}><path className="grid" d="M0 220L250 110 500 220M0 175L250 110 500 175M0 140L250 110 500 140M80 240L250 110 420 240M160 240L250 110 340 240M250 240V110"/><path className="object" d="M180 90L250 55 320 90 320 165 250 200 180 165ZM180 90L250 125 320 90M250 125V200M250 55V125"/><circle cx="250" cy="125" r="5"/></svg><div className="demo-engine-tag"><Box size={12}/>{id==='supersplat'?'SPLAT ENGINE SLOT':id==='pascal'?'PASCAL ENGINE SLOT':'3D ENGINE SLOT'}</div></div>;
}
export function WidgetDemo({id,state='ready',compact=false,onEvent}:{id:WidgetId;state?:WidgetState;compact?:boolean;onEvent?:(text:string)=>void}){const d=getWidgetDefinition(id),fixture=React.useMemo(()=>makeFixture(id),[id]);const [value,setValue]=React.useState(fixture.value),[items,setItems]=React.useState(fixture.items),[messages,setMessages]=React.useState(fixture.messages);const [pinned,setPinned]=React.useState(false),[dock,setDock]=React.useState<DockPosition>('free');const [currentState,setCurrentState]=React.useState(state);React.useEffect(()=>setCurrentState(state),[state]);
 const action=(action:string,item?:string)=>{onEvent?.(`${d.label}: ${action}${item?' · '+item:''}`);if(action==='send-message')setMessages(m=>[...m,{id:String(Date.now()),role:'human',name:'You',text:item||''}]);if(action==='approve')setItems(a=>a.map(x=>({...x,status:'ready'})));if(action==='revise')setItems(a=>a.map((x,i)=>i===0?{...x,status:'blocked'}:x));if(action==='execute')setValue(v=>({...v,text:'Cue triggered'}))};
 React.useEffect(()=>{if(!value.playing)return;const timer=setInterval(()=>setValue(v=>({...v,scalar:(v.scalar+1)%100})),1000);return()=>clearInterval(timer)},[value.playing]);
 return <WidgetFrame title={d.label} widgetId={id} state={currentState} active={!compact} pinned={pinned} onPinChange={setPinned} dock={dock} onDockChange={setDock} onRetry={()=>{setCurrentState('ready');onEvent?.('Recovered '+d.label)}} onDuplicate={compact?undefined:()=>onEvent?.('Duplicate requested · demo action only')} className={compact?'demo-widget-small':'demo-widget-large'}><WidgetView widgetId={id} value={value} onValueChange={setValue} items={items} messages={messages} samples={fixture.samples} description={fixture.description} onAction={action}>{d.implementation==='engine-slot'?<EngineMock id={id} value={value} onValueChange={setValue}/>:undefined}</WidgetView></WidgetFrame>;
}
export default function WidgetGallery(){const [query,setQuery]=React.useState(''),[category,setCategory]=React.useState('All'),[state,setState]=React.useState<WidgetState>('ready'),[theme,setTheme]=React.useState(()=>localStorage.getItem('nb-gallery-theme')||'dark'),[motionOn,setMotionOn]=React.useState(true),[event,setEvent]=React.useState('Ready to inspect'),[width,setWidth]=React.useState('full'),[tab,setTab]=React.useState('preview'),[selected,setSelected]=React.useState<WidgetId|undefined>(()=>{const id=location.hash.split('/')[2];return widgetCatalog.some(d=>d.id===id)?id as WidgetId:undefined});const [approved,setApproved]=React.useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('nb-widget-approvals')||'[]')}catch{return []}});
 React.useEffect(()=>{const fn=()=>{const id=location.hash.split('/')[2];setSelected(widgetCatalog.some(d=>d.id===id)?id as WidgetId:undefined)};window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn)},[]);
 React.useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.dataset.motion=motionOn?'on':'off';localStorage.setItem('nb-gallery-theme',theme)},[theme,motionOn]);
 const visible=widgetCatalog.filter(d=>(category==='All'||d.category===category)&&(!query||`${d.id} ${d.label} ${d.presentation}`.toLowerCase().includes(query.toLowerCase())));const detail=selected?getWidgetDefinition(selected):undefined;const open=(id:WidgetId)=>{location.hash='/widgets/'+id;setTab('preview');setState('ready')};const approve=()=>{if(!selected)return;const next=approved.includes(selected)?approved.filter(x=>x!==selected):[...approved,selected];setApproved(next);localStorage.setItem('nb-widget-approvals',JSON.stringify(next))};
 const code=detail?`import { NBrainProvider, WidgetFrame, WidgetView, defaultWidgetValue } from '@nbrain/ui';\nimport '@nbrain/ui/styles.css';\nimport '@nbrain/ui/fonts.css';\n\nconst [value, setValue] = useState(defaultWidgetValue);\n\n<NBrainProvider theme="dark">\n  <WidgetFrame title="${detail.label}" widgetId="${detail.id}">\n    <WidgetView widgetId="${detail.id}" value={value}\n      onValueChange={setValue} items={yourData}\n      onAction={handleAction}${detail.implementation==='engine-slot'?'\n    >\n      <YourEngine />\n    </WidgetView>':' />'}\n  </WidgetFrame>\n</NBrainProvider>`:'';
 return <MotionConfig reducedMotion={motionOn?'user':'always'}><TooltipProvider><div className="widget-catalog-page"><header className="catalog-topbar nb-glass"><a href="#/atelier"><Wordmark/></a><span className="catalog-topbar-label">UI SYSTEM / WIDGET ATLAS</span><Badge>0.3.1</Badge><div className="catalog-topbar-actions"><a className="nb-button button-outline button-sm" href="#/atelier">Component atelier</a><a className="nb-button button-outline button-sm" href="#/radial">Radial lab</a><Button size="icon" variant="ghost" aria-label="Toggle gallery theme" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={16}/>:<Moon size={16}/>}</Button></div></header><aside className="catalog-sidebar"><div className="catalog-search"><Search size={14}/><Input aria-label="Search widgets" placeholder="Find a widget…" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="eyebrow">COLLECTIONS</span><nav>{categories.map(c=><button key={c} className={category===c?'active':''} onClick={()=>{setCategory(c);if(selected)location.hash='/widgets'}}>{c}<span>{c==='All'?74:widgetCatalog.filter(d=>d.category===c).length}</span></button>)}</nav><div className="catalog-legend"><span><i/>Reusable controls</span><span><i/>Data-driven compositions</span><span><i/>Engine slots + design previews</span></div><div className="catalog-review-count"><strong>{approved.length}<small> / 74</small></strong><span>Widgets approved locally</span></div></aside><main className="catalog-main">{detail?<><div className="catalog-detail-heading"><Button variant="ghost" size="sm" onClick={()=>{location.hash='/widgets'}}><ArrowLeft size={14}/>All widgets</Button><div><span className="eyebrow">{detail.category.toUpperCase()} / {detail.id}</span><h1>{detail.label}</h1><p>{detail.implementation==='engine-slot'?'Styled engine host with a design preview. Connect your existing renderer for real production behavior.':detail.implementation==='control'?'Controlled UI component. Input changes are demonstrated locally.':'Reusable presentation composition. Data and execution belong to your application.'}</p></div><Button variant={approved.includes(detail.id)?'primary':'silver'} onClick={approve}><Check size={14}/>{approved.includes(detail.id)?'Approved':'Approve widget'}</Button></div><div className="catalog-detail-toolbar"><div className="catalog-tabs" role="tablist" aria-label="Widget documentation">{['preview','usage','contract'].map(t=><button role="tab" aria-selected={tab===t} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div><Select label="Widget state" value={state} onValueChange={s=>setState(s as WidgetState)} options={['ready','loading','empty','error','offline'].map(s=>({value:s,label:s}))}/><Select label="Preview width" value={width} onValueChange={setWidth} options={[{value:'full',label:'Fluid'},{value:'720',label:'Tablet / 720'},{value:'375',label:'Phone / 375'}]}/><Button size="sm" variant="ghost" aria-pressed={motionOn} onClick={()=>setMotionOn(!motionOn)}>Motion {motionOn?'on':'off'}</Button></div>{tab==='preview'?<div className="catalog-preview-stage"><div className="catalog-preview-width" style={{maxWidth:width==='full'?960:Number(width)}}><ConnectionBanner status={state==='offline'?'offline':'connected'} onReconnect={()=>setState('ready')}/><WidgetDemo key={detail.id} id={detail.id} state={state} onEvent={setEvent}/></div><span className="catalog-stage-caption">{detail.width} × {detail.height} ORIGINAL CANVAS SIZE · FLUID UI PREVIEW</span></div>:tab==='usage'?<div className="catalog-code"><div className="between row"><span className="eyebrow">REACT / TYPESCRIPT</span><Button size="sm" onClick={()=>navigator.clipboard?.writeText(code).then(()=>setEvent('Usage copied'))}><Copy size={13}/>Copy usage</Button></div><pre><code>{code}</code></pre></div>:<div className="catalog-contract"><h2>Integration contract</h2><dl><dt>Registry ID</dt><dd>{detail.id}</dd><dt>Presentation</dt><dd>{detail.presentation}</dd><dt>Implementation</dt><dd>{detail.implementation}</dd><dt>Original source</dt><dd>{detail.source}</dd><dt>Application data</dt><dd>Controlled value, items, messages, samples, and action callbacks.</dd><dt>Execution</dt><dd>Host-owned. No implicit networking, storage of production data, or backend dispatch.</dd><dt>States</dt><dd>Ready, loading, empty, error, offline.</dd></dl><p>The preview uses demo fixtures. It is not the original ShowControl widget engine.</p></div>}<div className="catalog-event-log" role="status"><span className="tiny-square"/>{event}</div></>:<><div className="catalog-hero"><div><span className="eyebrow">N’BRAIN / COMPLETE REGISTRY COVERAGE</span><h1>Every instrument.<br/><span>One visual language.</span></h1><p>74 widgets from your supplied registry. Inspect individual states, responsive widths, component contracts, and integration examples.</p></div><AgentCore size="lg"/></div><div className="catalog-coverage"><span><strong>74</strong> registry entries</span><span><strong>{widgetCatalog.filter(d=>d.implementation==='control').length}</strong> controls</span><span><strong>{widgetCatalog.filter(d=>d.implementation==='composition').length}</strong> compositions</span><span><strong>{widgetCatalog.filter(d=>d.implementation==='engine-slot').length}</strong> engine previews</span></div><div className="catalog-grid-heading"><span className="eyebrow">{category.toUpperCase()} / {visible.length} ITEMS</span><span className="muted small">Open a widget to review its full interface</span></div><div className="catalog-grid">{visible.map((d,i)=><motion.article key={d.id} className="catalog-card" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{duration:.2,delay:Math.min(i*.012,.15)}}><div className="catalog-card-meta"><span>{d.category}</span><Badge>{d.implementation==='engine-slot'?'Engine preview':d.implementation==='control'?'Control':'Composition'}</Badge></div><div className="catalog-card-preview" aria-hidden="true" {...{inert:""}}><WidgetDemo id={d.id} compact/></div><button className="catalog-card-open" onClick={()=>open(d.id)}><div><strong>{d.label}</strong><span>{d.id}</span></div>{approved.includes(d.id)?<Check size={16}/>:<ArrowUpRight size={18}/>}</button></motion.article>)}</div>{!visible.length&&<div className="catalog-no-results"><Search size={24}/><h2>No matching widgets</h2><Button onClick={()=>{setQuery('');setCategory('All')}}>Clear filters</Button></div>}</>}<footer className="catalog-footer">n’brain / UI SYSTEM <span>Fixtures are local. Specialized engines remain in the main application.</span></footer></main></div></TooltipProvider></MotionConfig>;
}
